#include "ContinuousTrajectory.hpp"
#include <iostream>
using namespace ContinuousMotion;
int main(){size_t sampled=0,retargets=0;std::vector<Origin> input;for(int i=0;i<64;++i)input.push_back({{double(i*19-600),double(i*13-500),double(40+i*3),double(50+i*2)},{0,0,0,0},{double(i*7+40),double(i*5+20),30,20}});FamilyTrajectory curve(input,.220);for(int turn=0;turn<40;++turn){std::vector<Origin> next;for(size_t i=0;i<input.size();++i){const auto old=curve.sample(i,curve.seconds()*(.11+.017*(turn%40)));const auto target=turn%2?Vector{double(int(i)*7+40),double(int(i)*5+20),30,20}:Vector{double(int(i)*19-600),double(int(i)*13-500),double(40+i*3),double(50+i*2)};next.push_back({old.rectangle,old.velocity,target});for(int j=0;j<=100;++j){const auto s=curve.sample(i,curve.seconds()*j/100);for(size_t k=0;k<4;++k)if(std::abs(s.rectangle[k])>400000||std::abs(s.velocity[k])>1e9)throw std::runtime_error("bounds");if(s.rectangle[2]<=0||s.rectangle[3]<=0)throw std::runtime_error("dimensions");++sampled;}}FamilyTrajectory following(next,.220);for(size_t i=0;i<next.size();++i){auto s=following.sample(i,0);if(s.rectangle!=next[i].rectangle||s.velocity!=next[i].velocity)throw std::runtime_error("origin pair");++retargets;}curve=following;input=next;}
size_t rejected=0;for(const auto& o:std::vector<Origin>{{{0,0,400000,1},{0,0,1e9,0},{0,0,400000,1}},{{0,0,1,1},{0,0,-1e9,0},{0,0,400000,1}}})try{FamilyTrajectory bad({o},4);}catch(const std::invalid_argument&){++rejected;}if(rejected!=2)throw std::runtime_error("old unsafe inputs accepted");std::cout<<"{\"result\":\"pass\",\"members\":64,\"turns\":40,\"exactOriginPairs\":"<<retargets<<",\"boundedSamples\":"<<sampled<<",\"v11CounterexamplesRefused\":"<<rejected<<",\"nativeAccepted\":false}\n";}
